'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Backtracking must undo constraints from abandoned choices.
assert.deepEqual(resolve({
  a: { '2.0.0': { c: '^2.0.0', b: '1.0.0' }, '1.0.0': { c: '^1.0.0' } },
  b: { '1.0.0': { c: '^1.0.0' } },
  c: { '1.0.0': {}, '2.0.0': {} },
}, { a: '*' }), { a: '1.0.0', c: '1.0.0' });

// Abandoned choice's deps must not stay reachable.
assert.deepEqual(resolve({
  a: { '2.0.0': { x: '1.0.0', y: '*' }, '1.0.0': {} },
  x: { '1.0.0': {} },
  y: {},
}, { a: '*' }), { a: '1.0.0' });

// Cycles and self deps.
assert.deepEqual(resolve({
  a: { '1.0.0': { b: '*', a: '1.0.0' } }, b: { '1.0.0': { a: '^1.0.0' } },
}, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
assert.equal(resolve({ a: { '1.0.0': { a: '2.0.0' } } }, { a: '*' }), null);

// Long chain without recursion or iteration cap.
const reg = {};
const N = 50000;
for (let i = 0; i < N; i += 1) reg['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '*' } : {}, '0.9.0': {} };
assert.equal(Object.keys(resolve(reg, { p0: '*' })).length, N);

// Missing package unsatisfiable; unreachable malformed throws; empty root.
assert.equal(resolve({}, { nope: '*' }), null);
assert.throws(() => resolve({ z: { '1.0': {} } }, {}), TypeError);
assert.throws(() => resolve({ z: { '1.0.0': { q: '' } } }, {}), TypeError);
assert.deepEqual(resolve({}, {}), {});

// Caret rules.
assert.equal(satisfies('0.2.9', '^0.2.3'), true);
assert.equal(satisfies('0.3.0', '^0.2.3'), false);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.0', '^1.2.3'), true);
assert.equal(compare('1.10.0', '1.9.0'), 1);
